files.content:
.root {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.control {
  position: relative;
  display: flex;
  align-items: flex-start;
  gap: 11px;
  cursor: pointer;
  color: var(--ink-body);
}

/* Visually hidden but still the real, focusable, form-posting control. */
.input {
  position: absolute;
  width: 18px;
  height: 18px;
  margin: 0;
  opacity: 0;
  cursor: inherit;
}

/* Off: white with a 3.9:1 border (the 3:1 non-text floor for a control
   whose only boundary is its outline). On: the brand gradient, as in
   the reference multi-select. */
.box {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  margin-top: 1px;
  border-radius: var(--r-2xs);
  background: var(--surface-solid);
  box-shadow: inset 0 0 0 1.5px var(--neutral-border);
  color: var(--ink-inverse);
  transition:
    background-color var(--dur) var(--ease),
    box-shadow var(--dur) var(--ease);
}

.tick,
.dash {
  display: none;
}

.control:hover .input:not(:disabled):not(:checked) + .box {
  box-shadow: inset 0 0 0 1.5px var(--brand), 0 0 0 3px rgba(var(--rgb-brand), 0.1);
}

.input:checked + .box,
.input:indeterminate + .box {
  background: var(--brand-gradient);
  box-shadow: var(--glow-sm);
}

.input:checked:not(:indeterminate) + .box .tick,
.input:indeterminate + .box .dash {
  display: block;
}

.input:focus-visible + .box {
  box-shadow: var(--focus-ring);
}

.input:checked:focus-visible + .box {
  box-shadow: var(--focus-ring), var(--glow-sm);
}

.input:active:not(:disabled) + .box {
  transform: translateY(0.5px);
}

.invalid .input:not(:checked) + .box {
  background: var(--danger-field-fill);
  box-shadow: inset 0 0 0 1.5px var(--danger-base);
}

.disabled {
  cursor: not-allowed;
}

.input:disabled + .box {
  background: var(--surface-sunken);
  box-shadow: inset 0 0 0 1.5px rgba(var(--rgb-brand-deep), 0.16);
}

.input:disabled:checked + .box {
  background: rgba(var(--rgb-brand-deep), 0.22);
  box-shadow: none;
}

.disabled .label,
.disabled .description {
  color: var(--ink-disabled);
}

.text {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.label {
  font-size: var(--text-body);
  line-height: 1.5;
}

.description {
  font-size: var(--text-caption);
  line-height: 1.5;
  color: var(--ink-muted);
}

/* ── Card: the opt-in box, rebuilt as a white tile that takes the brand
   wash when ticked ─────────────────────────────────────────────────────── */

.card {
  padding: 14px 16px;
  border-radius: var(--r-lg);
  background: rgba(var(--rgb-white), 0.72);
  box-shadow: inset 0 0 0 1px var(--line), 0 1px 2px rgba(var(--rgb-contact), 0.04);
  transition:
    background-color var(--dur) var(--ease),
    box-shadow var(--dur) var(--ease);
}

.card .input {
  top: 15px;
  left: 16px;
}

.card:hover:not(.disabled) {
  background: var(--surface-solid);
  box-shadow: inset 0 0 0 1px rgba(var(--rgb-brand), 0.3), 0 2px 6px rgba(var(--rgb-brand-deep), 0.06);
}

.card:has(.input:checked) {
  background: linear-gradient(135deg, rgba(var(--rgb-brand), 0.09), rgba(var(--rgb-brand-deep), 0.04)), var(--surface-solid);
  box-shadow: inset 0 0 0 1.5px rgba(var(--rgb-brand), 0.55), 0 2px 8px rgba(var(--rgb-brand), 0.1);
}

.card.invalid:not(:has(.input:checked)) {
  background: var(--danger-field-fill);
  box-shadow: inset 0 0 0 1.5px rgba(var(--rgb-danger), 0.6);
}

.card .label {
  font-weight: 700;
  color: var(--ink-heading);
}

.error {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  font-size: 12.5px;
  font-weight: 700;
  line-height: 1.4;
  color: var(--danger-ink);
}

.error svg {
  margin-top: 1px;
}

"use client";

import { useId, type ComponentPropsWithRef, type ReactNode } from "react";
import { cx } from "../_internal/cx";
import { mergeRefs } from "../_internal/merge-refs";
import { mergeDescribedBy } from "../Field/Field";
import { IconAlertCircle, IconCheck, IconMinus } from "../Icon/Icon";
import styles from "./Checkbox.module.css";

export type CheckboxProps = Omit<ComponentPropsWithRef<"input">, "type" | "size"> & {
  label: ReactNode;
  description?: ReactNode;
  indeterminate?: boolean;
  /** Error text for a standalone checkbox (a declaration, accepting the terms). */
  error?: ReactNode;
  invalid?: boolean;
  /**
   * plain = box and label.
   * card  = a bordered opt-in box that washes accent when ticked (declarations,
   *         an opt-in to email updates).
   */
  variant?: "plain" | "card";
};

/** Native checkbox, visually replaced. Keeps native keyboard, form and label behaviour. */
export function Checkbox({
  label,
  description,
  indeterminate,
  error,
  invalid: invalidProp,
  variant = "plain",
  className,
  id: idProp,
  disabled,
  ref,
  "aria-describedby": describedByProp,
  ...rest
}: CheckboxProps) {
  const autoId = useId();
  const id = idProp ?? `cb-${autoId}`;
  const descId = description ? `${id}-desc` : undefined;
  const errorId = error ? `${id}-error` : undefined;
  const invalid = invalidProp ?? Boolean(error);

  const setIndeterminate = (el: HTMLInputElement | null) => {
    if (el) el.indeterminate = Boolean(indeterminate);
  };

  return (
    <div data-slot="checkbox" className={cx(styles.root, className)}>
      <label
        htmlFor={id}
        className={cx(styles.control, styles[variant], invalid && styles.invalid, disabled && styles.disabled)}
      >
        <input
          ref={mergeRefs(ref, setIndeterminate)}
          id={id}
          type="checkbox"
          className={styles.input}
          disabled={disabled}
          aria-invalid={invalid || undefined}
          aria-describedby={mergeDescribedBy(describedByProp, descId, errorId)}
          {...rest}
        />
        <span className={styles.box} aria-hidden="true">
          <IconCheck size={12} strokeWidth={3.2} className={styles.tick} />
          <IconMinus size={12} strokeWidth={3.2} className={styles.dash} />
        </span>
        <span className={styles.text}>
          <span className={styles.label}>{label}</span>
          {description ? (
            <span id={descId} className={styles.description}>
              {description}
            </span>
          ) : null}
        </span>
      </label>
      {error ? (
        <p id={errorId} className={styles.error}>
          <IconAlertCircle size={14} />
          <span>{error}</span>
        </p>
      ) : null}
    </div>
  );
}
